package br.com.sol7.olimpio.basico.cpfalunos.controller;
import br.com.sol7.olimpio.shared.PagedResponse;
import io.smallrye.mutiny.Uni; import jakarta.inject.Inject; import jakarta.validation.Valid; import jakarta.ws.rs.*; import jakarta.ws.rs.core.*; import java.util.List;
import br.com.sol7.olimpio.basico.cpfalunos.dto.CpfAlunosRequest;
import br.com.sol7.olimpio.basico.cpfalunos.dto.CpfAlunosResponse;
import br.com.sol7.olimpio.basico.cpfalunos.service.CpfAlunosService;
@Path("/api/basico/cpf-alunos") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class CpfAlunosController { @Inject CpfAlunosService service; @GET public Uni<List<CpfAlunosResponse>> list(){return service.list();} @GET @Path("/paged") public Uni<PagedResponse<CpfAlunosResponse>> paged(@QueryParam("page") Integer page,@QueryParam("size") Integer size){return service.paged(page==null?0:page,size==null?10:size);} @GET @Path("/{id}") public Uni<CpfAlunosResponse> find(@PathParam("id") Long id){return service.find(id);}@POST public Uni<Response> create(@Valid CpfAlunosRequest r){return service.create(r).map(item->Response.status(Response.Status.CREATED).entity(item).build());}@PUT @Path("/{id}") public Uni<CpfAlunosResponse> update(@PathParam("id") Long id,@Valid CpfAlunosRequest r){return service.update(id,r);}@DELETE @Path("/{id}") public Uni<Void> delete(@PathParam("id") Long id){return service.delete(id);} }